<template><PageShell title="开票" tcode="VF01"><template #actions><el-button type="primary" @click="visible=true">创建发票</el-button></template><el-card><el-table :data="rows" border stripe><el-table-column prop="vbeln" label="发票" /><el-table-column prop="dnVbeln" label="交货单" /><el-table-column prop="kunnr" label="客户" /><el-table-column prop="belnr" label="FI凭证" /><el-table-column prop="gross" label="含税金额" /><el-table-column label="操作"><template #default="{row}"><el-button link @click="show(row)">明细</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" title="从发货交货单创建发票"><el-select v-model="form.dnVbeln"><el-option v-for="x in deliveries" :key="x.vbeln" :label="x.vbeln" :value="x.vbeln" /></el-select><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="create">过账</el-button></template></el-dialog><el-drawer v-model="drawer" title="开票明细"><pre>{{JSON.stringify(selected,null,2)}}</pre></el-drawer></PageShell></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import PageShell from '../../components/PageShell.vue'; import { sdApi } from '../../api'; const rows=ref([]),deliveries=ref([]),visible=ref(false),drawer=ref(false),selected=ref(null),form=reactive({dnVbeln:''});async function load(){rows.value=await sdApi.billings();deliveries.value=(await sdApi.dns()).filter(x=>x.status==='PGI')};async function create(){await sdApi.createBilling(form);visible.value=false;load()};async function show(r){selected.value=await sdApi.billing(r.vbeln);drawer.value=true};onMounted(load)
</script>
